from future.utils import with_metaclass

from abc import abstractmethod
from abc import ABCMeta
import json
from copy import deepcopy
from collections import namedtuple
from tempfile import NamedTemporaryFile
from ta5g_scfc.interface import ta5g_scfc
import xmltodict


XmlWriterData = namedtuple('XmlWriterData', ['class_name', 'version'])


class Writer(with_metaclass(ABCMeta, object)):
    @abstractmethod
    def write(self, reversed_dict, extended_dict, output_dir):
        pass


class XmlWriter(Writer):
    @staticmethod
    def _extend_basic_dict(reversed_dict, extended_dict):
        result = deepcopy(reversed_dict)
        for element in result:
            key = element['distName']
            element['version'] = extended_dict[key].version
            element['class'] = extended_dict[key].class_name
        return result

    def _renamed_dict(self, reversed_dict, extended_dict):
        renamed_dict = self._extend_basic_dict(reversed_dict, extended_dict)
        for element in renamed_dict:
            element['@distName'] = element.pop('distName')
            element['@operation'] = element.pop('operation')
            element['@version'] = element.pop('version')
            element['@class'] = element.pop('class')
            element['p'] = element.pop('parameters')
            self._renamed_parameters(element)
            self._modify_parameters_if_list(element)
        return renamed_dict

    @staticmethod
    def _renamed_parameters(element):
        for parameter in element['p']:
            parameter["@name"] = parameter.pop('parameterName')
            if parameter['operation'] == "delete":
                parameter.pop('operation')
                parameter.pop('value')
                parameter["#text"] = None
            else:
                parameter.pop('operation')
                parameter["#text"] = parameter.pop('value')

    def _modify_parameters_if_list(self, element):
        for parameter in element['p']:
            if isinstance(parameter["#text"], list):
                for items in parameter["#text"]:
                    if isinstance(items, dict):
                        dists_of_param = self._create_dicts_for_item(parameter)
                        element['list'] = {"item": element.pop('p'), "@name": parameter["@name"]}
                        element['list']["item"] = {'p': dists_of_param}
                        return
                    else:
                        element["list"] = element.pop("p")
                        for value in element["list"]:
                            value['p'] = value.pop('#text')
                        return

    @staticmethod
    def _create_dicts_for_item(parameter):
        dicts_for_item = []
        for param in parameter["#text"]:
            for item in param:
                dicts_for_item.append({"#text": param[item], "@name": item})
        return dicts_for_item

    @staticmethod
    def _extend_dict_for_xml_conventer(renamed_dict):
        extend_dict = {
            'raml': {
                '@xmlns': 'raml21.xsd',
                'cmData': {
                    'header': {
                        'log': {
                            '@action': 'created',
                            '@user': 'BTSSM',
                            '@appInfo': 'Nokia BTS Site Manager',
                            '@appversion': renamed_dict[0]['@version'],
                            '@dateTime': '2016-03-24T07:40:52',
                        }
                    },
                    '@scope': 'all',
                    '@id': '3221225472',
                    '@type': 'plan',
                    'managedObject': renamed_dict,
                },
            }
        }
        return extend_dict

    def _convert_dicts_to_xml(self, reversed_dict, extended_dict):
        renamed_dict = self._renamed_dict(reversed_dict, extended_dict)
        dicts = self._extend_dict_for_xml_conventer(renamed_dict)
        return xmltodict.unparse(dicts, pretty=True).replace("></p>", "/>").replace("></log>", "/>")

    @staticmethod
    def _fix_version_attributes(scf_file, output_dir, file_name_prefix):
        fixed_delta = NamedTemporaryFile(
            prefix='%s-fixed' % file_name_prefix, suffix='.xml', dir=output_dir, delete=False
        )
        fixed_delta.close()
        ta5g_scfc().change_version_value_in_scf_based_on_adaptationversions_file_from_enb(
            scf_file.name, fixed_delta.name
        )
        return fixed_delta

    def write(self, reversed_dict, extended_dict, output_dir):
        rollback_delta = self._convert_dicts_to_xml(reversed_dict, extended_dict)
        xml_file = NamedTemporaryFile(prefix='rollback', suffix='.xml', dir=output_dir, delete=False, mode='w')
        xml_file.write(rollback_delta)
        xml_file.close()
        fixed_rollback_delta = self._fix_version_attributes(xml_file, output_dir, file_name_prefix='rollback')
        return fixed_rollback_delta


class JsonWriter(Writer):
    def write(self, reversed_dict, _, output_dir):
        rollback_delta = self._convert_dicts_to_json(reversed_dict)
        json_file = NamedTemporaryFile(prefix='rollback', suffix='.json', dir=output_dir, delete=False, mode='w')
        json_file.write(rollback_delta)
        json_file.close()
        return json_file

    @staticmethod
    def _convert_dicts_to_json(reversed_dict):
        return json.dumps(reversed_dict, sort_keys=True, indent=4)
